  magenta: '#ff40ff',
  green: '#20e020',
  cyan: '#00f0ff',
  yellow: '#ffe000',
  amber: '#ffb000',
  red: '#ff2020',
  gray: '#8a8a8a',
  tape: 'rgba(40, 40, 40, 0.62)',
  tapeSolid: '#2b2b2b',
  readout: '#000000',
  /** Airspeed arcs. */
  arcWhite: '#ffffff',
